options(stringsAsFactors = FALSE)
suppressPackageStartupMessages({library(data.table); library(Matrix); library(Seurat); library(RANN)})
root <- "D:/PDAC_P1"; indir <- file.path(root,"data/02_scrna_external/GSE282302/raw"); outdir <- file.path(root,"analysis/09_spatial_validation/GSE282302/spatial_ecology"); dir.create(outdir,recursive=TRUE,showWarnings=FALSE)
marker_sets <- list(malignant=c("EPCAM","KRT8","KRT18","KRT19","KRT7","KRT17","MSLN","CEACAM6","MUC1"), CAF=c("COL1A1","COL1A2","DCN","LUM","COL3A1","SPARC","FAP","PDGFRA","PDGFRB","ACTA2"), myeloid=c("LST1","TYROBP","FCER1G","CTSS","AIF1","LILRB1","LGALS3","LYZ","S100A8","S100A9"), T_NK=c("CD3D","CD3E","TRBC1","TRBC2","NKG7","GNLY","KLRD1"), endothelial=c("EMCN","PECAM1","VWF","KDR","RAMP2","ESAM","ENG"))
score_set <- function(log_cpm, genes) {present<-intersect(genes,rownames(log_cpm)); if(!length(present)) return(rep(NA_real_,ncol(log_cpm))); colMeans(t(scale(t(log_cpm[present,,drop=FALSE]))),na.rm=TRUE)}
matrix_files <- list.files(indir,pattern="_filtered_feature_bc_matrix\\.h5$",full.names=TRUE); results<-vector("list",length(matrix_files)); patient_rows<-vector("list",length(matrix_files)); spot_rows<-vector("list",length(matrix_files))
for(i in seq_along(matrix_files)) {f<-matrix_files[i]; sample_id<-sub("_filtered_feature_bc_matrix\\.h5$","",basename(f)); message("Processing ",i,"/",length(matrix_files),": ",sample_id); counts<-Read10X_h5(f); if(is.list(counts)) counts<-counts[[1]]; rownames(counts)<-make.unique(rownames(counts)); lib<-Matrix::colSums(counts); needed<-unique(c("EPAS1",unlist(marker_sets))); present<-intersect(needed,rownames(counts)); log_cpm<-log2(sweep(counts[present,,drop=FALSE],2,lib/1e6,"/")+1); scores<-as.data.table(lapply(marker_sets,function(g)score_set(log_cpm,g))); setnames(scores,names(marker_sets)); scores[,EPAS1:=if("EPAS1"%in%rownames(log_cpm))as.numeric(log_cpm["EPAS1",])else NA_real_]; pos<-fread(file.path(indir,paste0(sample_id,"_tissue_positions_list.csv.gz")),header=FALSE); setnames(pos,c("barcode","in_tissue","array_row","array_col","pxl_row_in_fullres","pxl_col_in_fullres")); pos<-pos[match(colnames(counts),barcode)]; d<-cbind(pos,scores); d<-d[in_tissue==1]; d[,sample:=sample_id]; d[,patient:=sub(".*_(D[0-9]+)(?:_.*)?$","\\1",sample_id)]; q25<-quantile(d$EPAS1,.25,na.rm=TRUE); q75<-quantile(d$EPAS1,.75,na.rm=TRUE); d[,EPAS1_group:=if(q75>q25)fifelse(EPAS1>=q75,"high",fifelse(EPAS1<=q25,"low","middle"))else "middle"]; xy<-as.matrix(d[,.(pxl_col_in_fullres,pxl_row_in_fullres)]); nn<-RANN::nn2(xy,k=min(7,nrow(d)))$nn.idx[,-1,drop=FALSE]; for(lineage in names(marker_sets)) {v<-d[[lineage]]; neigh<-apply(nn,1,function(ix)mean(v[ix],na.rm=TRUE)); d[[paste0(lineage,"_neighbor_score")]]<-neigh}; high<-d[EPAS1_group=="high"]; low<-d[EPAS1_group=="low"]; results[[i]]<-data.table(sample=sample_id,patient=unique(d$patient),n_spots=nrow(d),n_EPAS1_high=nrow(high),n_EPAS1_low=nrow(low),EPAS1_median=median(d$EPAS1,na.rm=TRUE),EPAS1_endothelial_rho=if(q75>q25)cor(d$EPAS1,d$endothelial,use="complete.obs",method="spearman")else NA_real_,CAF_neighbor_delta=if(nrow(high)>0&&nrow(low)>0)median(high$CAF_neighbor_score,na.rm=TRUE)-median(low$CAF_neighbor_score,na.rm=TRUE)else NA_real_,myeloid_neighbor_delta=if(nrow(high)>0&&nrow(low)>0)median(high$myeloid_neighbor_score,na.rm=TRUE)-median(low$myeloid_neighbor_score,na.rm=TRUE)else NA_real_,T_NK_neighbor_delta=if(nrow(high)>0&&nrow(low)>0)median(high$T_NK_neighbor_score,na.rm=TRUE)-median(low$T_NK_neighbor_score,na.rm=TRUE)else NA_real_,malignant_neighbor_delta=if(nrow(high)>0&&nrow(low)>0)median(high$malignant_neighbor_score,na.rm=TRUE)-median(low$malignant_neighbor_score,na.rm=TRUE)else NA_real_); patient_rows[[i]]<-data.table(patient=unique(d$patient),sample=sample_id,CAF_high_minus_low=results[[i]]$CAF_neighbor_delta,myeloid_high_minus_low=results[[i]]$myeloid_neighbor_delta,T_NK_high_minus_low=results[[i]]$T_NK_neighbor_delta,malignant_high_minus_low=results[[i]]$malignant_neighbor_delta); spot_rows[[i]]<-d[,.(sample,patient,barcode,array_row,array_col,pxl_row_in_fullres,pxl_col_in_fullres,EPAS1,EPAS1_group,malignant,CAF,myeloid,T_NK,endothelial,malignant_neighbor_score,CAF_neighbor_score,myeloid_neighbor_score,T_NK_neighbor_score,endothelial_neighbor_score)] }
roi<-rbindlist(results,fill=TRUE); patient<-rbindlist(patient_rows,fill=TRUE); spots<-rbindlist(spot_rows,fill=TRUE); patient_summary<-patient[,.(n_ROI=.N,median_CAF_delta=median(CAF_high_minus_low,na.rm=TRUE),median_myeloid_delta=median(myeloid_high_minus_low,na.rm=TRUE),median_T_NK_delta=median(T_NK_high_minus_low,na.rm=TRUE),median_malignant_delta=median(malignant_high_minus_low,na.rm=TRUE),proportion_CAF_positive=mean(CAF_high_minus_low>0,na.rm=TRUE),proportion_myeloid_positive=mean(myeloid_high_minus_low>0,na.rm=TRUE),proportion_T_NK_positive=mean(T_NK_high_minus_low>0,na.rm=TRUE)),by=patient]; fwrite(roi,file.path(outdir,"GSE282302_spatial_ecology_ROI.tsv"),sep="\t"); fwrite(patient_summary,file.path(outdir,"GSE282302_spatial_ecology_patient.tsv"),sep="\t"); fwrite(spots,file.path(outdir,"GSE282302_spatial_ecology_spots.tsv"),sep="\t"); writeLines(c("# GSE282302 spatial multi-lineage ecology","",paste0("- Six-neighbor spatial scores were calculated for ",nrow(roi)," ROIs across ",uniqueN(roi$patient)," patients."),"- Spot programmes use conservative marker sets derived from the annotated scRNA workflow.","- EPAS1-high and EPAS1-low groups are defined within each ROI by upper/lower quartiles; neighborhood deltas are descriptive spatial support analyses.","- Patient, not spot, is the replication unit. These scores do not replace single-cell deconvolution and do not establish cell-cell causality."),file.path(outdir,"GSE282302_spatial_ecology_report.md"))
